-- Complemento do FIXTURE_esquema_minimo.sql para testar a 017 num Postgres
-- descartável: public.bruto com o check de produção, colunas que faltam em
-- execucao_ingestao e app.pode_ver_geocodigo (como em 002/011, simplificada:
-- vê tudo quem não tem organização municipal). Só para testes.
create table if not exists public.bruto (
  id            bigint generated always as identity primary key,
  fonte         text not null,
  endpoint      text not null,
  parametros    jsonb not null default '{}'::jsonb,
  status_http   integer,
  obtido_em     timestamptz not null default now(),
  sha256        text,
  tamanho_bytes integer,
  corpo         text,
  constraint bruto_fonte_check check (fonte in ('ibge','infodengue','genbank','nextclade'))
);
alter table public.execucao_ingestao add column if not exists mensagem text;
create or replace function app.pode_ver_geocodigo(g integer) returns boolean
  language sql stable set search_path = '' as $$ select true $$;
-- os 167 municípios do RN (geocódigo e nome do IBGE, copiados de public.municipio em 14/11/2026)
on conflict do nothing;
